const observer=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.1});document.querySelectorAll('.reveal').forEach(n=>observer.observe(n));const steps=[...document.querySelectorAll('.step')],screens=[...document.querySelectorAll('.stack img')];function update(){let best=Infinity,index=0;steps.forEach((n,i)=>{const r=n.getBoundingClientRect(),d=Math.abs(r.top+r.height/2-innerHeight/2);if(d<best){best=d;index=i}});screens.forEach((n,i)=>n.classList.toggle('active',i===index));const max=document.documentElement.scrollHeight-innerHeight;document.querySelector('.progress').style.width=(max?scrollY/max*100:0)+'%'}let pending=false;addEventListener('scroll',()=>{if(!pending){pending=true;requestAnimationFrame(()=>{update();pending=false})}},{passive:true});addEventListener('resize',update);update();const modes={"home": "data:image/png;base64,", "dark": "data:image/png;base64,"};document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-mode]').forEach(n=>n.setAttribute('aria-pressed',String(n===b)));const im=document.querySelector('.mode-image');im.src=modes[b.dataset.mode];im.alt='Foody '+b.textContent+' mode home'}));